    'josh_riley', 'joyce_beatty', 'juan_ciscomani', 'juan_vargas',
    'judy_chu', 'julia_brownley', 'julia_letlow', 'julie_johnson',
    'kat_cammack', 'kathy_castor', 'keith_self', 'kelly_morrison',
    'ken_calvert', 'kevin_kiley', 'kevin_mullin', 'kim_schrier',
    'kristen_mcdonald_rivet', 'kweisi_mfume', 'lamonica_mciver', 'lance_gooden',
    'lateefah_simon', 'laura_friedman', 'laura_gillen', 'laurel_lee',
    'lauren_underwood', 'linda_sanchez', 'lizzie_fletcher', 'lloyd_doggett',
    'lloyd_smucker', 'lois_frankel', 'lori_trahan', 'lucy_mcbath',
    'luz_rivas', 'madeleine_dean', 'maggie_goodlander', 'marc_veasey',
    'marcy_kaptur', 'maria_salazar', 'marilyn_strickland', 'mario_diaz_balart',
    'mark_alford', 'mark_amodei', 'mark_desaulnier', 'mark_harris',
    'mark_messmer', 'mark_pocan', 'marlin_stutzman', 'mary_miller',
    'mary_scanlon', 'matt_van_epps', 'max_miller', 'maxine_dexter',
    'michael_baumgartner', 'michael_cloud', 'michael_mccaul', 'michael_rulli',
    'michael_turner', 'michelle_fischbach', 'mike_carey', 'mike_haridopolos',
    'mike_kelly', 'mike_levin', 'mike_quigley', 'mike_rogers_al',
    'mike_thompson', 'monica_de_la_cruz', 'morgan_luttrell', 'morgan_mcgarvey',
    'nancy_pelosi', 'nanette_barragan', 'nathaniel_moran', 'neal_dunn',
    'nellie_pou', 'nicholas_begich', 'nicholas_langworthy', 'nicolas_lalota',
    'nicole_malliotakis', 'nicole_nikki_budzinski', 'nikema_williams', 'norma_torres',
    'nydia_velazquez', 'pat_fallon', 'pat_harrigan', 'patrick_ryan',
    'paul_gosar', 'paul_tonko', 'pete_sessions', 'pete_stauber',
    'pfluger', 'ralph_norman', 'randy_feenstra', 'randy_weber',
    'raul_ruiz', 'rfine', 'rich_mccormick', 'rick_allen',
    'riley_moore', 'robert_aderholt', 'robert_latta', 'robert_menendez',
    'robert_onder', 'robert_wittman', 'robin_kelly', 'ron_estes',
    'ronny_jackson', 'rudy_yakym', 'russell_fry', 'ryan_zinke',
    'salud_carbajal', 'sam_liccardo', 'sanford_bishop', 'sara_jacobs',
    'sarah_elfreth', 'scott_desjarlais', 'scott_fitzgerald', 'scott_peters',
    'sean_casten', 'seth_magaziner', 'sharice_davids', 'sheri_biggs',
    'shomari_figures', 'shontel_brown', 'shri_thanedar', 'stephen_lynch',
    'steve_cohen', 'steven_horsford', 'suhas_subramanyam', 'suzanne_bonamici',
    'sydney_kamlager_dove', 'sylvia_garcia', 'terri_sewell', 'thomas_kean',
    'thomas_tiffany', 'tim_burchett', 'tim_moore', 'timothy_kennedy',
    'tom_barrett', 'tom_mcclintock', 'tony_wied', 'tracey_mann',
    'troy_balderson', 'troy_carter', 'troy_nehls', 'valerie_foushee',
    'valerie_hoyle', 'vern_buchanan', 'veronica_escobar', 'vicente_gonzalez',
    'victoria_spartz', 'vince_fong', 'w_steube', 'warren_davidson',
    'wesley_bell', 'wesley_hunt', 'william_keating', 'william_timmons',
    'yassamin_ansari', 'young_kim', 'yvette_clarke'
  ];
  n integer;
BEGIN
  SELECT array_agg(r.id ORDER BY r.id) INTO roll_ids FROM vr_rollcalls r
   WHERE r.chamber = 'house' AND (r.congress, r.session, r.roll_number) IN (
     (119, 1, 171), (119, 1, 244), (119, 1, 246), (119, 1, 248), (119, 1, 249), (119, 1, 251), (119, 1, 252), (119, 1, 270), (119, 1, 271), (119, 1, 277), (119, 1, 279), (119, 1, 298), (119, 1, 323), (119, 1, 330), (119, 1, 334), (119, 1, 342), (119, 1, 347), (119, 1, 356), (119, 1, 358), (119, 2, 55), (119, 2, 134), (119, 2, 148), (119, 2, 152)
   );
  SELECT array_agg(DISTINCT r.measure_id) INTO measure_ids FROM vr_rollcalls r WHERE r.id = ANY(roll_ids);

  IF coalesce(array_length(roll_ids, 1), 0) <> 23 THEN
    RAISE EXCEPTION 'Federal roster wave R1: expected 23 roll calls in scope, found %', coalesce(array_length(roll_ids, 1), 0);
  END IF;
  IF coalesce(array_length(wave_slugs, 1), 0) <> 315 THEN
    RAISE EXCEPTION 'Federal roster wave R1: the emitted slug list is % long, not 315', coalesce(array_length(wave_slugs, 1), 0);
  END IF;

  -- THE CELLS LANDED, AND THE COUNT IS THE SEED'S. Stored-before plus written equals
  -- stored-after; a re-run finds the same number because every insert is ON CONFLICT DO
  -- NOTHING, which is also why this guard is an equality and not a lower bound.
  SELECT count(*) INTO n FROM vr_member_votes v WHERE v.rollcall_id = ANY(roll_ids);
  IF n <> 9818 THEN
    RAISE EXCEPTION 'Federal roster wave R1: expected 9818 member votes on this wave''s 23 rolls (2680 stored before + 7138 written), found %', n;
  END IF;
  SELECT count(*) INTO n FROM vr_member_votes v WHERE v.rollcall_id = ANY(roll_ids) AND v.politician_id = ANY(wave_slugs);
  IF n <> 7138 THEN
    RAISE EXCEPTION 'Federal roster wave R1: expected 7138 cells on this wave''s own slugs, found %', n;
  END IF;

  -- ONE PERSON, ONE FILE. No cell on these rolls belongs to a politician_id that is
  -- neither already-mapped nor admitted by this wave, so a typo in the slug list would
  -- surface here rather than as an orphan page nobody can reach.
  SELECT count(DISTINCT v.politician_id) INTO n FROM vr_member_votes v WHERE v.rollcall_id = ANY(roll_ids);
  IF n <> 431 THEN
    RAISE EXCEPTION 'Federal roster wave R1: expected 431 distinct slugs holding a cell on these 23 rolls (117 before + 314 newly admitted), found %', n;
  END IF;

  -- TWO LIVING PEOPLE WITH ONE NAME STAY TWO FILES. mike_rogers is the former Michigan
  -- congressman and House Intelligence chair; mike_rogers_al is the sitting member for
  -- Alabama's 3rd, admitted by this wave under a deliberately distinct slug. The Michigan
  -- file must hold no cell on a 119th House roll, because he was not in this chamber. This
  -- is the guard against the failure the King-Hinds/Kennedy collision already cost once.
  SELECT count(*) INTO n FROM vr_member_votes v WHERE v.rollcall_id = ANY(roll_ids) AND v.politician_id = 'mike_rogers';
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal roster wave R1: % cell(s) on these rolls were attributed to mike_rogers, who is a different living person from mike_rogers_al and was not in the 119th House.', n;
  END IF;

  -- THE POSITION AND is_party VOCABULARIES ARE CLOSED.
  SELECT count(*) INTO n FROM vr_member_votes v WHERE v.rollcall_id = ANY(roll_ids)
     AND v.position NOT IN ('yea', 'nay', 'present', 'not_voting');
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal roster wave R1: % member vote(s) carry a position outside the closed vocabulary.', n;
  END IF;
  SELECT count(*) INTO n FROM vr_member_votes v WHERE v.rollcall_id = ANY(roll_ids)
     AND v.is_party IS NOT NULL AND v.is_party NOT IN ('with_party', 'against_party');
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal roster wave R1: % member vote(s) carry an is_party outside the closed vocabulary.', n;
  END IF;

  -- THE TALLY IS STILL THE CHAMBER'S. This wave adds 7,138 rows to these rolls and must
  -- not have touched a single total: a roll whose stored totals were recomputed from its
  -- attributed rows would now publish a vote the House never took. Each roll still
  -- accounts for a full chamber.
  SELECT count(*) INTO n FROM vr_rollcalls r WHERE r.id = ANY(roll_ids)
     AND (r.totals->>'yea')::int + (r.totals->>'nay')::int
       + coalesce((r.totals->>'present')::int, 0) + coalesce((r.totals->>'notVoting')::int, 0)
       NOT BETWEEN 425 AND 441;
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal roster wave R1: % roll(s) no longer account for a full House.', n;
  END IF;

  -- F8's PULL RULE, RE-CHECKED AGAINST THE DATABASE. The attributed set is a SUBSET of
  -- the chamber. Judged rows outnumbering the document's own yea+nay pool means a cell on
  -- one of these rolls belongs to nobody the House lists — the shape of senate 119/1 roll
  -- 7, which three document reads walked past and a verification block like this one
  -- caught at deploy time. The wave refuses the roll rather than deleting the row.
  SELECT count(*) INTO n FROM vr_rollcalls r WHERE r.id = ANY(roll_ids)
     AND (r.totals->>'yea')::int + (r.totals->>'nay')::int
       < (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id = r.id AND v.position IN ('yea', 'nay'));
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal roster wave R1: % roll(s) hold more judged rows than the Clerk''s own yea+nay pool. A repair with its own citation is owed; do not trim it here.', n;
  END IF;

  -- NO MEASURE READING MOVED. The issue rows on these 23 rolls' measures are exactly the
  -- ones that were there before: this wave argues about who voted, never about what the
  -- vote meant, so a new mapping or a new key appearing here is this wave exceeding itself.
  SELECT count(*) INTO n FROM vr_measure_issues i WHERE i.measure_id = ANY(measure_ids);
  IF n <> 25 THEN
    RAISE EXCEPTION 'Federal roster wave R1: expected the same 25 issue row(s) on these rolls'' measures as before the wave, found %. This wave writes no mapping and no key.', n;
  END IF;

  -- NO STANCE HARVEST. Not one stated position exists for any member this wave admitted.
  -- These are recorded votes; a stance is a different claim with a different citation.
  SELECT count(*) INTO n FROM vr_positions p WHERE p.politician_id = ANY(wave_slugs);
  IF n > 0 THEN
    RAISE EXCEPTION 'Federal roster wave R1: % stated position(s) exist for newly admitted members. This wave harvests no stances.', n;
  END IF;

  RAISE NOTICE 'Federal roster wave R1 verified: % member votes on % House roll calls, % of them on the wave''s own slugs; 0 measures, 0 roll calls, 0 issue mappings, 0 stated positions, 0 deletions.',
    (SELECT count(*) FROM vr_member_votes WHERE rollcall_id = ANY(roll_ids)),
    array_length(roll_ids, 1),
    (SELECT count(*) FROM vr_member_votes WHERE rollcall_id = ANY(roll_ids) AND politician_id = ANY(wave_slugs));
END $$;
